/* ------------------------------ DOM helpers ------------------------------ */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

// Escape data at HTML text/quoted-attribute boundaries, never stored values.
// Markup passed to shell(), modal() and table() is generated by the app only.
function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, character => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[character]);
}

// HTML escaping does not make executable URL schemes safe.
function safeLinkUrl(value) {
  const text = String(value ?? "").trim();
  try {
    const url = new URL(text, "https://schoolshield.invalid/");
    return ["https:", "http:"].includes(url.protocol) ? text : "#";
  } catch { return "#"; }
}
function safeImageUrl(value) {
  const text = String(value ?? "").trim();
  if (/^data:image\/(?:png|jpeg|webp|gif);base64,[a-z0-9+/=\s]+$/i.test(text)) return text;
  try {
    const url = new URL(text, "https://schoolshield.invalid/");
    return ["https:", "http:", "blob:"].includes(url.protocol) ? text : "";
  } catch { return ""; }
}

