/* -------------------------- workspace data source ------------------------- */
// Operational data is loaded from and saved to Supabase. The empty shape only
// protects a newly created, as-yet-unpopulated school workspace.
const WORKSPACE_VERSION = 13;
function subjectsForGrade(grade) {
  const state = getState();
  const schoolClasses = state.classes.filter(c => String(c.grade).replace(/\D/g,'') === String(grade).replace(/\D/g,''));
  const names = new Set(schoolClasses.flatMap(c => c.subjects || []));
  for (const assessment of state.assessments) if (schoolClasses.some(c => c.id === assessment.class)) names.add(assessment.subject);
  return state.subjects.filter(subject => names.size === 0 || names.has(subject.name)).map(subject => subject.name);
}
function subjectsForClass(classId) {
  const state = getState(), schoolClass = state.classes.find(c => c.id === classId);
  const offered = new Set(schoolClass?.subjects || []);
  return state.subjects.filter(s => offered.has(s.name)).map(s => s.name);
}
function emptyWorkspace() {
  return {
    __v: WORKSPACE_VERSION,
    classes: [],
    learners: [],
    assessments: [],
    reports: [],
    announcements: [],
    visitors: [],
    incidents: [],
    notifications: [],
    staff: [],
    staffChangeRequests: [],
    security: [],
    securityAttendance: [],
    sickNotices: [],
    appointments: [],
    teacherChat: [],
    parentChat: [],
    sgbPrincipalChat: [],
    attendanceRegisters: [],
    attendanceWeeks: [],
    chatExtras: [],
    reportRequests: [],
    teacherAssignments: [],
    subjects: [],
    grades: [],
  };
}

/* ------------------------------ state layer ------------------------------ */
function workspaceCacheKey() {
  const session = JSON.parse(sessionStorage.getItem("schoolshieldSession") || "{}");
  return `schoolshield:${session.schoolCode || SCHOOL.code}:${session.userId || "signed-out"}`;
}

function getState() {
  let stored = null;
  try {
    stored = JSON.parse(
      sessionStorage.getItem(workspaceCacheKey()) || "null",
    );
  } catch (err) {
    stored = null;
  }
  if (!stored || typeof stored !== "object") {
    stored = emptyWorkspace();
    return stored;
  }
  // Merge into a new object. Mutating `stored` while using it as a later
  // Object.assign source erased populated arrays (for example parent learners).
  stored = { ...emptyWorkspace(), ...stored, __v: WORKSPACE_VERSION };
  return stored;
}

function save(state) {
  const cacheKey = workspaceCacheKey();
  const before = window.schoolshieldWorkspaceLocalSnapshot || window.schoolshieldWorkspaceConfirmed;
  const snapshot = JSON.parse(JSON.stringify(state));
  for (const [key, records] of Object.entries(snapshot)) {
    if (!Array.isArray(records) || ['subjects','grades'].includes(key)) continue;
    for (const record of records) {
      if (record && typeof record === 'object' && !Array.isArray(record) && !record.id) record.id = crypto.randomUUID();
    }
  }
  sessionStorage.setItem(cacheKey, JSON.stringify(snapshot));
  window.schoolshieldWorkspaceLocalSnapshot = snapshot;
  if (!window.schoolshieldCloudWorkspaceReady || !window.schoolshieldSupabase || !before) {
    window.schoolshieldLastSyncError = 'Load the authoritative school dataset before saving.';
    window.schoolshieldWorkspaceSaveQueue = Promise.resolve(false);
    return window.schoolshieldWorkspaceSaveQueue;
  }
  const previous = window.schoolshieldWorkspaceSaveQueue || Promise.resolve(true);
  window.schoolshieldWorkspaceSaveQueue = previous.then(async (saved) => {
    if (workspaceCacheKey() !== cacheKey) return false;
    if (!saved || saved.error) {
      const pending = JSON.parse(sessionStorage.getItem(`${cacheKey}:pending`) || 'null');
      sessionStorage.setItem(`${cacheKey}:pending`, JSON.stringify({ before: pending?.before || before, after: snapshot }));
      return false;
    }
    const {data, error} = await window.schoolshieldSupabase.rpc('save_school_dataset', {
      p_before: before, p_after: snapshot,
    });
    if (workspaceCacheKey() !== cacheKey) return false;
    if (error) {
      window.schoolshieldLastSyncError = error.message;
      sessionStorage.setItem(`${cacheKey}:pending`, JSON.stringify({ before, after: snapshot }));
      console.warn('School workspace sync failed', error.message);
      return false;
    }
    if (workspaceCacheKey() !== cacheKey) return false;
    window.schoolshieldWorkspaceConfirmed = data.payload;
    window.schoolshieldIdentityIssues = data.identityIssues || [];
    window.schoolshieldLastSyncError = '';
    if (window.schoolshieldWorkspaceLocalSnapshot === snapshot) {
      window.schoolshieldWorkspaceLocalSnapshot = data.payload;
      sessionStorage.setItem(workspaceCacheKey(), JSON.stringify(data.payload));
      sessionStorage.removeItem(`${cacheKey}:pending`);
    }
    return true;
  }).catch(error => {
    if (workspaceCacheKey() !== cacheKey) return false;
    window.schoolshieldLastSyncError = error.message;
    sessionStorage.setItem(`${cacheKey}:pending`, JSON.stringify({ before, after: snapshot }));
    return false;
  });
  return window.schoolshieldWorkspaceSaveQueue;
}

async function retrySchoolDraft() {
  const pending = JSON.parse(sessionStorage.getItem(`${workspaceCacheKey()}:pending`) || 'null');
  if (!pending || !window.schoolshieldSupabase) return;
  const {data,error} = await window.schoolshieldSupabase.rpc('save_school_dataset', {p_before: pending.before, p_after: pending.after});
  if (error) return modal('Draft not saved', `<p>${announcementText(error.message)} The draft is still retained in this tab.</p>`);
  sessionStorage.removeItem(`${workspaceCacheKey()}:pending`);
  sessionStorage.setItem(workspaceCacheKey(), JSON.stringify(data.payload));
  window.schoolshieldWorkspaceSaveQueue = Promise.resolve(true);
  window.schoolshieldWorkspaceConfirmed = data.payload;
  window.schoolshieldWorkspaceLocalSnapshot = data.payload;
  window.schoolshieldIdentityIssues = data.identityIssues || [];
  window.schoolshieldLastSyncError = '';
  render();
  modal('Draft saved', '<p>Supabase confirmed your changes.</p>');
}

async function refreshCloudWorkspace(renderAfterRefresh = false) {
  if (window.schoolshieldWorkspaceSaveQueue)
    if (!await window.schoolshieldWorkspaceSaveQueue) return false;
  const client = window.schoolshieldSupabase;
  const session = JSON.parse(
    sessionStorage.getItem("schoolshieldSession") || "{}",
  );
  if (!client || !session.schoolId) return false;
  if (client.auth?.getSession) {
    const { data: own, error } = await client.from("profiles")
      .select("role,display_name,account_status,requires_setup,onboarding_completed_at")
      .eq("id", session.userId).maybeSingle();
    if (error) throw new Error("Could not verify your account. Check your connection.");
    if (!own || own.account_status === "Inactive" || (own.requires_setup && !own.onboarding_completed_at)) {
      sessionStorage.removeItem("schoolshieldSession");
      await client.auth.signOut();
      location.replace("login.html");
      return false;
    }
    session.role = own.role;
    session.displayName = own.display_name;
    sessionStorage.setItem("schoolshieldSession", JSON.stringify(session));
  }
  if (session.role === "parent") {
    const previousError = window.schoolshieldParentWorkspaceError;
    const previousLinked = window.schoolshieldParentLearnerLinked;
    const fail = (message) => {
      window.schoolshieldParentWorkspaceError = message;
      if (renderAfterRefresh && previousError !== message) render();
      return false;
    };
    let response;
    try {
      response = await window.schoolshieldFunctionRequest("parent-workspace");
    } catch (error) {
      return fail(error.message || "Check your connection and try again.");
    }
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data?.payload) {
      return fail(data?.error || `Request failed (${response.status})`);
    }
    window.schoolshieldParentWorkspaceError = "";
    const key = workspaceCacheKey();
    const incoming = JSON.stringify(data.payload);
    const changed = sessionStorage.getItem(key) !== incoming;
    sessionStorage.setItem(key, incoming);
    window.schoolshieldParentLearnerLinked = Boolean(data.linked);
    if (renderAfterRefresh && (changed || previousError || previousLinked !== Boolean(data.linked))) render();
    return changed;
  }
  const { data, error } = await client.rpc('read_school_dataset');
  if (error || !data?.payload) {
    window.schoolshieldLastSyncError = error?.message || 'School dataset is not available.';
    return false;
  }
  window.schoolshieldLastSyncError = '';
  window.schoolshieldWorkspaceConfirmed = data.payload;
  window.schoolshieldWorkspaceLocalSnapshot = data.payload;
  window.schoolshieldIdentityIssues = data.identityIssues || [];
  const key = workspaceCacheKey();
  const incoming = JSON.stringify(data.payload);
  const changed = sessionStorage.getItem(key) !== incoming;
  sessionStorage.setItem(key, incoming);
  window.schoolshieldCloudWorkspaceReady = true;
  if (changed && renderAfterRefresh) render();
  return changed;
}

// Keep receiving even when Realtime is unavailable (parents use a restricted
// endpoint). Schedule after completion so slow requests never overlap.
function startWorkspaceAutoRefresh() {
  if (window.schoolshieldAutoRefreshStarted) return;
  window.schoolshieldAutoRefreshStarted = true;
  let pending = null;
  const refresh = () => {
    if (document.visibilityState === "hidden") return Promise.resolve();
    if (!pending) {
      pending = refreshCloudWorkspace(true)
        .then(async result => { await loadTeachingAssignmentNotifications(true); return result; })
        .catch((error) => console.warn("Automatic workspace refresh failed", error.message))
        .finally(() => { pending = null; });
    }
    return pending;
  };
  const schedule = () => {
    const chatPage = ["parent-chat", "teacher-chat", "sgb-chat"].includes(page());
    window.schoolshieldWorkspaceRefreshTimer = setTimeout(async () => {
      await refresh();
      schedule();
    }, chatPage ? 3000 : 15000);
  };
  window.addEventListener("focus", refresh);
  window.addEventListener("online", refresh);
  document.addEventListener("visibilitychange", refresh);
  schedule();
}

async function refreshWorkspaceManually() {
  const changed = await refreshCloudWorkspace(true);
  const message = window.schoolshieldLastSyncError
    ? `The latest data could not be loaded: ${window.schoolshieldLastSyncError}`
    : changed
      ? "The latest school data has been loaded."
      : "This workspace is already up to date.";
  modal(
    window.schoolshieldLastSyncError ? "Refresh failed" : "Workspace refreshed",
    `<p>${escapeHtml(message)}</p><div class="modal-foot"><button class="btn primary" data-action="close-modal">Done</button></div>`,
  );
}

function startWorkspaceRealtime() {
  const client = window.schoolshieldSupabase;
  const session = JSON.parse(
    sessionStorage.getItem("schoolshieldSession") || "{}",
  );
  if (
    !client ||
    !session.schoolId ||
    window.schoolshieldWorkspaceChannel
  )
    return;
  const channel = client
    .channel(`school-workspace:${session.schoolId}`)
    .on(
      "postgres_changes",
      {
        event: "UPDATE",
        schema: "public",
        table: "school_dataset_versions",
        filter: `school_id=eq.${session.schoolId}`,
      },
      () => { refreshCloudWorkspace(true); },
    )
    .on("postgres_changes", { event: "*", schema: "public", table: "account_request_notifications", filter: `recipient_id=eq.${session.userId}` }, () => loadTeachingAssignmentNotifications(true))
    .subscribe();
  window.schoolshieldWorkspaceChannel = channel;
}

async function connectCloudWorkspace() {
  window.schoolshieldCloudWorkspaceReady = false;
  window.schoolshieldWorkspaceConfirmed = null;
  window.schoolshieldWorkspaceLocalSnapshot = null;
  // A browser cache is never bootstrap data, even when the server read fails.
  sessionStorage.removeItem(workspaceCacheKey());
  await refreshCloudWorkspace();
}

function persist(mutator) {
  const state = getState();
  mutator(state);
  save(state);
  return state;
}

function role() {
  try {
    const session = JSON.parse(
      sessionStorage.getItem("schoolshieldSession") || "null",
    );
    if (session?.role && ROLE_NAMES[session.role]) return session.role;
  } catch (err) {
    /* Legacy demo sessions continue below. */
  }
  return sessionStorage.getItem("schoolshieldRole") || "principal";
}
function userName() {
  try {
    const session = JSON.parse(
      sessionStorage.getItem("schoolshieldSession") || "null",
    );
    if (session?.displayName) return session.displayName;
  } catch (err) {
    /* The sign-in guard redirects before any workspace is rendered. */
  }
  return ROLE_NAMES[role()] || "Member";
}
function page() {
  return document.body.dataset.page || "dashboard";
}
function param(name) {
  return new URLSearchParams(location.search).get(name);
}
function allowed(target = page()) {
  if (target === "account-requests")
    return ["principal", "clerk"].includes(role());
  return (ACCESS[role()] || []).includes(target);
}
function go(url) {
  location.href = "./" + url;
}
function isLeadership() {
  return role() === "principal" || role() === "deputy";
}

/* --------------------------- domain: collections ------------------------- */
function classes() {
  return getState().classes;
}
function learners() {
  return getState().learners;
}
function classById(id) {
  return classes().find((c) => c.id === id);
}
function learnerById(id) {
  return learners().find((l) => l.id === id);
}
function learnersInClass(classId) {
  return learners().filter((l) => l.class === classId);
}
function teacherForClass(classId) {
  return classById(classId)?.teacher || "Unassigned";
}
function teacherClasses(teacherName) {
  const session = JSON.parse(sessionStorage.getItem('schoolshieldSession') || '{}');
  if (session.userId) return classes().filter(c => c.teacherProfileId === session.userId || (c.teacherProfileIds || []).includes(session.userId));
  return [];
}

/* Grades in curriculum order, each with its classes. */
function gradeGroups() {
  const order = [];
  const map = new Map();
  for (const c of classes()) {
    if (!map.has(c.grade)) {
      map.set(c.grade, []);
      order.push(c.grade);
    }
    map.get(c.grade).push(c);
  }
  return order.map((grade) => ({ grade, classes: map.get(grade) }));
}

/* ------------------------------- averages -------------------------------- */
function mean(values) {
  const nums = values.filter((v) => typeof v === "number" && !isNaN(v));
  if (!nums.length) return 0;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

/* Attendance, class average and pass rate for one class. */
function classStats(classId) {
  const list = learnersInClass(classId);
  const attendance = Math.round(mean(list.map((l) => l.attendance)));
  const courseAverage = Math.round(mean(list.map((l) => l.average)));
  const passing = list.filter((l) => l.average >= 50).length;
  const passRate = list.length ? Math.round((passing / list.length) * 100) : 0;
  return {
    learners: list.length,
    attendance,
    courseAverage,
    passRate,
    passing,
  };
}

/* Average across every learner in a grade. */
function gradeStats(grade) {
  const list = learners().filter((l) => l.grade === grade);
  const attendance = Math.round(mean(list.map((l) => l.attendance)));
  const courseAverage = Math.round(mean(list.map((l) => l.average)));
  const passing = list.filter((l) => l.average >= 50).length;
  const passRate = list.length ? Math.round((passing / list.length) * 100) : 0;
  return {
    learners: list.length,
    attendance,
    courseAverage,
    passRate,
    passing,
  };
}

function schoolStats() {
  const list = learners();
  const attendance = Math.round(mean(list.map((l) => l.attendance)));
  const courseAverage = Math.round(mean(list.map((l) => l.average)));
  const passing = list.filter((l) => l.average >= 50).length;
  const passRate = list.length ? Math.round((passing / list.length) * 100) : 0;
  return {
    learners: list.length,
    attendance,
    courseAverage,
    passRate,
    passing,
  };
}

function standingFor(learner) {
  if (learner.average >= 50) return "Pass";
  return "At Risk";
}

/* Average score for a single assessment. */
function assessmentAverage(assessment) {
  return Math.round(mean(Object.values(assessment.scores || {})));
}

/* Average of every captured assessment in a class. */
function classTestAverage(classId) {
  const list = getState().assessments.filter((a) => a.class === classId);
  const all = list.flatMap((a) => Object.values(a.scores || {}));
  return Math.round(mean(all));
}

function assessmentsForClass(classId) {
  return getState().assessments.filter((a) => a.class === classId);
}

