/* Teacher submits marks; clerk corrects marks already submitted. */
function saveAttendance(classId) {
  const date = inputValue("attendanceDate");
  if (!date) return;
  const entries = Object.fromEntries(
    $$("[data-attendance]").map((input) => [
      input.dataset.attendance,
      input.value,
    ]),
  );
  persist((state) => {
    state.attendanceRegisters = state.attendanceRegisters || [];
    const index = state.attendanceRegisters.findIndex(
      (register) => register.class === classId && register.date === date,
    );
    const register = {
      class: classId,
      date,
      teacher: userName(),
      entries,
      capturedOn: todayLabel(),
    };
    if (index >= 0) state.attendanceRegisters[index] = register;
    else state.attendanceRegisters.unshift(register);
    const classRegisters = state.attendanceRegisters.filter(
      (item) => item.class === classId,
    );
    state.learners
      .filter((learner) => learner.class === classId)
      .forEach((learner) => {
        const absenceCount = classRegisters.reduce(
          (total, item) =>
            total +
            (["Absent", "Sick", "Excused"].includes(item.entries?.[learner.id])
              ? 1
              : 0),
          0,
        );
        learner.absentDays = (learner.initialAbsentDays || 0) + absenceCount;
        const totalDays =
          (learner.attendanceDays || 60) + classRegisters.length;
        learner.attendance = Math.max(
          0,
          Math.round(((totalDays - learner.absentDays) / totalDays) * 100),
        );
      });
  });
  render();
}
function saveWeeklyAttendance(classId, weekStart) {
  const inputs = $$("[data-week-status]");
  const weekly = {};
  inputs.forEach((input) => {
    const learnerId = input.dataset.weekLearner;
    const day = input.dataset.weekDay;
    weekly[day] = weekly[day] || {};
    if (!weekly[day][learnerId]) weekly[day][learnerId] = "Present";
    if (input.checked && input.dataset.weekStatus !== "Present")
      weekly[day][learnerId] = input.dataset.weekStatus;
  });
  persist((state) => {
    state.attendanceRegisters = state.attendanceRegisters || [];
    Object.entries(weekly).forEach(([date, entries]) => {
      const index = state.attendanceRegisters.findIndex(
        (register) => register.class === classId && register.date === date,
      );
      const register = {
        class: classId,
        date,
        teacher: userName(),
        entries,
        capturedOn: todayLabel(),
      };
      if (index >= 0) state.attendanceRegisters[index] = register;
      else state.attendanceRegisters.unshift(register);
    });
    state.attendanceWeeks = state.attendanceWeeks || [];
    const summary = {
      class: classId,
      weekStart,
      teacher: userName(),
      updatedOn: todayLabel(),
    };
    const weekIndex = state.attendanceWeeks.findIndex(
      (week) => week.class === classId && week.weekStart === weekStart,
    );
    if (weekIndex >= 0) state.attendanceWeeks[weekIndex] = summary;
    else state.attendanceWeeks.unshift(summary);
    const classRegisters = state.attendanceRegisters.filter(
      (item) => item.class === classId,
    );
    state.learners
      .filter((learner) => learner.class === classId)
      .forEach((learner) => {
        const absences = classRegisters.reduce(
          (total, register) =>
            total +
            (["Absent", "Excused", "Sick"].includes(
              register.entries?.[learner.id],
            )
              ? 1
              : 0),
          0,
        );
        learner.absentDays = (learner.initialAbsentDays || 0) + absences;
        const totalDays =
          (learner.attendanceDays || 60) + classRegisters.length;
        learner.attendance = Math.max(
          0,
          Math.round(((totalDays - learner.absentDays) / totalDays) * 100),
        );
      });
  });
  render();
}

function saveTestScores(classId, mode, assessmentId = "") {
  const inputs = $$("[data-score]");
  const scores = {};
  for (const input of inputs) {
    const raw = input.value.trim();
    const value = Number(raw);
    if (raw !== "" && (isNaN(value) || value < 0 || value > 100)) {
      modal(
        "Invalid score",
        `<p class="muted">Enter a score between 0 and 100. "${escapeHtml(raw)}" is not valid.</p>`,
      );
      return;
    }
    if (raw !== "") scores[input.dataset.score] = value;
  }
  let savedAssessment = null;
  let criticalLearners = [];
  persist((state) => {
    const assessment =
      state.assessments.find((a) => a.id === assessmentId) ||
      state.assessments.find((a) => a.class === classId);
    if (assessment) {
      assessment.scores = { ...assessment.scores, ...scores };
      criticalLearners = Object.entries(assessment.scores || {}).filter(([, score]) => Number(score) < 40).map(([learnerId, score]) => {
        const learner = state.learners.find((item) => item.id === learnerId);
        return learner ? { id: learner.id, name: learner.name, score: Number(score) } : null;
      }).filter(Boolean);
      const classTeacher = state.classes.find((item) => item.id === classId)?.teacher;
      criticalLearners.forEach((learner) => {
        const alreadyAlerted = state.notifications.some((notice) => notice.category === "Critical mark" && notice.scope === "teacher" && notice.assessmentId === assessment.id && notice.learnerId === learner.id);
        if (!alreadyAlerted) state.notifications.unshift({
          id: crypto.randomUUID(),
          createdAt: notificationTimestamp(),
          category: "Critical mark",
          scope: "teacher",
          recipient: classTeacher,
          recipientId: state.classes.find(item => item.id === classId)?.teacherProfileId,
          priority: "High",
          title: `Critical ${assessment.subject} mark requires attention`,
          description: `${learner.name} scored ${learner.score}% in ${assessment.title}. Decide whether to contact the learner's parent.`,
          class: classId,
          assessmentId: assessment.id,
          learnerId: learner.id,
          read: false,
        });
      });
      if (mode === "teacher") {
        assessment.status = "submitted";
        assessment.submittedBy = userName();
        assessment.date = todayLabel();
        state.notifications.unshift({
          id: crypto.randomUUID(),
          createdAt: notificationTimestamp(),
          category: "Assessment scores",
          scope: "clerk",
          priority: "Medium",
          title: `${assessment.subject} scores ready for review`,
          description: `${userName()} submitted ${assessment.title} scores for ${classId}.`,
          class: classId,
          assessmentId: assessment.id,
          read: false,
        });
      }
      if (mode === "clerk" && assessment.status === "draft") {
        assessment.status = "submitted";
        assessment.submittedBy = userName();
      }
      savedAssessment = { id: assessment.id, title: assessment.title, subject: assessment.subject, captured: Object.keys(scores).length };
    }
    if (mode === "teacher") {
      const report = state.reports.find((r) => r.class === classId);
      if (report && report.status === "awaiting-marks") {
        report.status = "ready";
        report.marksSubmittedOn = todayLabel();
      }
    }
  });
  if (mode === "teacher") criticalLearners.forEach((learner) => sessionStorage.setItem(`schoolshield:critical-popup:${SCHOOL.code}:${savedAssessment?.id}:${learner.id}`, "shown"));
  render();
  if (mode === "teacher" && savedAssessment) {
    const followUps = criticalLearners.map((learner) => `<div class="report-row"><span><b>${escapeHtml(learner.name)}</b><small>${escapeHtml(savedAssessment.subject)} · ${escapeHtml(learner.score)}% (critical)</small></span><button class="btn small" data-action="notify-parent-critical-subject" data-assessment="${escapeHtml(savedAssessment.id)}" data-learner="${escapeHtml(learner.id)}">Contact parent</button></div>`).join("");
    const criticalSection = criticalLearners.length ? `<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Parent contact decision</h3><p>These learners have a critical mark. Contact their parent about this subject where appropriate.</p></div></div>${followUps}</section>` : "";
    modal("Scores submitted to clerk", `<p><b>${escapeHtml(savedAssessment.subject)} — ${escapeHtml(savedAssessment.title)}</b> has been submitted for ${escapeHtml(classId)}.</p><p class="muted">${escapeHtml(savedAssessment.captured)} learner score${escapeHtml(savedAssessment.captured === 1 ? " was" : "s were")} captured. The clerk has been alerted and can review the marks immediately.</p>${criticalSection}<div class="modal-foot"><button class="btn primary" data-action="close-modal">Done</button></div>`);
  }
}
