function submitTeacherAssignment() {
  const classId = inputValue("assignmentClass");
  const teacherStaffId = inputValue("assignmentTeacher");
  const selectedTeacher = getState().staff.find(t => t.entityId === teacherStaffId);
  const teacher = selectedTeacher?.name;
  if (!requireValues([classId, teacher])) return;
  persist((state) => {
    state.teacherAssignments = state.teacherAssignments || [];
    state.teacherAssignments.unshift({
      id: crypto.randomUUID(),
      teacherStaffId,
      teacherId: selectedTeacher.profileId || null,
      class: classId,
      teacher,
      requestedBy: userName(),
      requestedOn: todayLabel(),
      status: "Pending",
    });
  });
  finishForm();
}
function approveTeacherAssignment(id) {
  persist((state) => {
    const assignment = (state.teacherAssignments || []).find(
      (item) => item.id === id,
    );
    const schoolClass =
      assignment && state.classes.find((item) => item.id === assignment.class);
    if (!assignment || !schoolClass) return;
    schoolClass.teacherStaffId = assignment.teacherStaffId;
    schoolClass.teacher = assignment.teacher;
    assignment.status = "Approved";
    assignment.approvedBy = userName();
    state.notifications.unshift({
      id: crypto.randomUUID(),
      createdAt: notificationTimestamp(),
      category: "Class update",
      priority: "Medium",
      title: `New class teacher for ${schoolClass.class || schoolClass.id}`,
      description: `${assignment.teacher} is now the class teacher for ${schoolClass.grade} ${schoolClass.id}.`,
      scope: "parents",
      class: schoolClass.id,
      read: false,
    });
  });
  render();
}
function addAssessment(classId = "") {
  const classOptions = classes()
    .map((schoolClass) => `<option value="${escapeHtml(schoolClass.id)}" ${escapeHtml(schoolClass.id === classId ? "selected" : "")}>${escapeHtml(schoolClass.grade)} · ${escapeHtml(schoolClass.id)} — ${escapeHtml(schoolClass.teacher)}</option>`)
    .join("");
  modal("Add assessment", `<p class="muted">Set the assessment details first. Saving opens the full class mark sheet.</p><div class="form-grid"><label>Class<select class="select" id="assessmentClass">${classOptions}</select></label><label>Subject<select class="select" id="assessmentSubject">${subjectsForClass(classId || classes()[0]?.id).map(name => `<option>${announcementText(name)}</option>`).join("")}</select></label><label>Assessment title<input class="input" id="assessmentTitle" placeholder="e.g. Controlled Test 1"></label><label>Assessment type<select class="select" id="assessmentType"><option>Test</option><option>Assignment</option><option>Practical</option><option>Project</option><option>Exam</option></select></label><label>Term<select class="select" id="assessmentTerm"><option>${escapeHtml(TERM)}</option><option>Term 1</option><option>Term 3</option><option>Term 4</option></select></label><label>Date<input class="input" id="assessmentDate" type="date"></label><label>Weighting (%)<input class="input" id="assessmentWeight" type="number" min="1" max="100" value="20"></label><label>Total marks<input class="input" id="assessmentTotal" type="number" min="1" value="100"></label><label class="full">Assessment instructions / notes<textarea class="textarea" id="assessmentNotes" placeholder="Optional instructions or moderation notes"></textarea></label></div><div class="modal-foot"><button class="btn primary" data-action="save-assessment">Save & capture marks</button></div>`);
  const updateSubjects = () => {
    const names = subjectsForClass(inputValue("assessmentClass"));
    document.getElementById("assessmentSubject").innerHTML = names.map(name => `<option>${announcementText(name)}</option>`).join("");
    const saveButton = document.querySelector('[data-action="save-assessment"]');
    saveButton.disabled = !names.length;
    if (!names.length) document.getElementById("assessmentSubject").innerHTML = '<option value="">No subjects assigned for this class</option>';
  };
  document.getElementById("assessmentClass").onchange = updateSubjects;
  updateSubjects();
}
function saveAssessment() {
  const classId = inputValue("assessmentClass");
  const subject = inputValue("assessmentSubject");
  const title = inputValue("assessmentTitle");
  const date = inputValue("assessmentDate");
  if (!requireValues([classId, subject, title, date])) return;
  if (date > todayIso()) return modal("Future date not allowed", '<p class="muted">Assessment dates cannot be after today.</p>');
  const schoolClass = classById(classId);
  if (!schoolClass) return;
  const id = crypto.randomUUID();
  persist((state) =>
    state.assessments.unshift({
      id,
      class: classId,
      grade: schoolClass.grade,
      subject,
      title,
      type: inputValue("assessmentType"),
      term: inputValue("assessmentTerm"),
      date,
      weighting: Number(inputValue("assessmentWeight")),
      total: Number(inputValue("assessmentTotal")),
      notes: inputValue("assessmentNotes"),
      status: "draft",
      submittedBy: "",
      scores: {},
    }),
  );
  $$(".modal-backdrop").forEach((element) => element.remove());
  go(`test-scores.html?class=${classId}&subject=${encodeURIComponent(subject)}&assessment=${id}`);
}

function setReportStatus(classId, status) {
  persist((state) => {
    const report = state.reports.find((r) => r.class === classId);
    const schoolClass = state.classes.find((item) => item.id === classId);
    if (!report) return;
    report.status = status;
    if (status === "compiled") report.compiledOn = todayLabel();
    if (status === "finalised") report.finalisedOn = todayLabel();
    if (status === "published") report.publishedOn = todayLabel();
    if (status === "compiled" && schoolClass)
      state.notifications.unshift({
        id: crypto.randomUUID(),
        title: `${classId} learner reports ready for review`,
        description: `The clerk compiled ${TERM} reports for your class. Review every learner report before release.`,
        category: "Reports",
        priority: "Medium",
        createdAt: notificationTimestamp(),
        read: false,
        scope: "teacher",
        class: classId,
        recipient: schoolClass.teacher,
        recipientId: schoolClass.teacherProfileId,
      });
    if (status === "published" && schoolClass)
      state.notifications.unshift({
        id: crypto.randomUUID(),
        title: `${TERM} learner reports released`,
        description: `Your child’s ${TERM} academic report is now available to view and download.`,
        category: "Reports",
        priority: "Medium",
        createdAt: notificationTimestamp(),
        read: false,
        scope: "parents",
        class: schoolClass.id,
      });
  });
  render();
}
function reviewLearnerReport(classId, learnerId) {
  persist((state) => {
    const report = state.reports.find((item) => item.class === classId);
    if (!report || report.status !== "compiled") return;
    report.learnerReviews = report.learnerReviews || {};
    report.learnerReviews[learnerId] = { by: userName(), date: todayLabel() };
  });
  render();
}
function releaseLearnerReport(classId, learnerId) {
  persist((state) => {
    const report = state.reports.find((item) => item.class === classId);
    const learner = state.learners.find(
      (item) => item.id === learnerId && item.class === classId,
    );
    if (
      !report ||
      !learner ||
      !report.learnerReviews?.[learnerId] ||
      !["finalised", "published"].includes(report.status)
    )
      return;
    report.releasedLearners = report.releasedLearners || {};
    report.releasedLearners[learnerId] = todayLabel();
    state.notifications.unshift({
      id: crypto.randomUUID(),
      title: `${TERM} report available for ${learner.name}`,
      description: `${learner.name}'s reviewed term report is ready to view and download.`,
      category: "Reports",
      priority: "Medium",
      createdAt: notificationTimestamp(),
      read: false,
      scope: "parents",
      learnerId,
    });
    const total = state.learners.filter(
      (item) => item.class === classId,
    ).length;
    if (Object.keys(report.releasedLearners).length >= total) {
      report.status = "published";
      report.publishedOn = todayLabel();
    }
  });
  render();
}

function announcementText(value) {
  return escapeHtml(value);
}
function announcementIsVisible(item) {
  const session = JSON.parse(sessionStorage.getItem('schoolshieldSession') || '{}');
  if ((item.authorId && item.authorId === session.userId) || (!session.userId && !item.authorId && item.author === userName())) return true;
  const audience = item.audienceId;
  if (!audience) return true; // Preserve legacy notices without audience IDs.
  const r = role();
  if (audience === 'whole-school') return true;
  if (audience === 'all-parents') return r === 'parent';
  if (audience === 'all-learners') return false;
  if (audience === 'all-staff') return ['principal','deputy','clerk','teacher','security'].includes(r);
  if (audience === 'teachers') return r === 'teacher';
  if (audience === 'leadership') return ['principal','deputy'].includes(r);
  if (audience === 'administration') return r === 'clerk';
  if (audience === 'sgb' || audience === 'security') return r === audience;
  if (r !== 'parent') return false;
  const children = learners();
  if (audience === 'my-classes-parents') return children.some(child => (item.classIds || []).includes(child.class));
  if (audience.startsWith('class-')) return children.some(child => child.class === audience.slice(6));
  if (audience.startsWith('grade-')) return children.some(child => String(child.grade).replace(/\s+/g,'-') === audience.slice(6));
  return false;
}
async function writeAnnouncement(params) {
  if (!['principal','deputy','clerk','teacher'].includes(role())) throw new Error('You are not permitted to publish announcements.');
  const client = window.schoolshieldSupabase;
  if (!client || !window.schoolshieldCloudWorkspaceReady) throw new Error('The school workspace is unavailable. Refresh and try again.');
  if (window.schoolshieldWorkspaceSaveQueue) await window.schoolshieldWorkspaceSaveQueue.catch(() => undefined);
  const pending = Promise.resolve(client.rpc('publish_school_announcement', params));
  window.schoolshieldWorkspaceSaveQueue = pending;
  const { data, error } = await pending;
  if (error || !data) throw new Error(error?.message || 'The announcement could not be saved.');
  // Update only the announcement cache after the server confirms persistence.
  const state = getState();
  state.announcements = state.announcements.filter(item => item.id !== data.id);
  if (params.p_action !== 'delete') state.announcements.unshift(data);
  const oldNotice = state.notifications.find(item => item.announcementId === data.id);
  state.notifications = state.notifications.filter(item => item.announcementId !== data.id);
  if (params.p_action !== 'delete') state.notifications.unshift({ ...oldNotice, ...data, id: 'NOTICE-' + data.id, announcementId: data.id, description: data.body, reporter: data.author, category: 'Announcement', priority: 'Medium', read: oldNotice?.read || false });
  sessionStorage.setItem(workspaceCacheKey(), JSON.stringify(state));
  return data;
}
async function sendAnnouncement() {
  if (window.schoolshieldAnnouncementSending) return;
  const title = inputValue('annTitle'), body = inputValue('annBody');
  const audience = audienceOptions().find(option => option.id === inputValue('audienceSelect'));
  if (!title || !body || !audience) { modal('Missing information','<p>Enter a title, message and valid audience before publishing.</p>'); return; }
  const delivery = inputValue('deliverySelect');
  const signature = JSON.stringify([title,body,audience.id,delivery]);
  // Keep the same ID after uncertain network errors so retries cannot duplicate a saved notice.
  if (window.schoolshieldAnnouncementDraft?.signature !== signature) window.schoolshieldAnnouncementDraft = { signature, id: 'ANN-' + crypto.randomUUID() };
  const button = $("[data-action='send-announcement']");
  window.schoolshieldAnnouncementSending = true;
  if (button) button.disabled = true;
  try {
    await writeAnnouncement({ p_id: window.schoolshieldAnnouncementDraft.id, p_title: title, p_body: body, p_audience_id: audience.id, p_audience: audience.label, p_delivery: delivery, p_recipients: audience.count, p_action: 'create' });
    window.schoolshieldAnnouncementDraft = null;
    $('#annTitle').value = ''; $('#annBody').value = '';
    render();
  } catch (error) { modal('Announcement not saved', '<p>' + announcementText(error.message) + '</p>'); }
  finally {
    window.schoolshieldAnnouncementSending = false;
    if (button) button.disabled = false;
    const current = $("[data-action='send-announcement']");
    if (current) current.disabled = false;
  }
}

async function sendMessage(storeKey, chatIndex = 0, sender = "me") {
  const input = $("#chatInput");
  if (!input || !input.value.trim() || window.schoolshieldChatSending) return;
  const text = input.value.trim();
  if (["parent", "teacher"].includes(role()) && storeKey === "parentChat") {
    const child =
      role() === "parent"
        ? parentLearner()
        : getState().parentChat?.[Number(chatIndex) || 0] &&
          learnerById(getState().parentChat[Number(chatIndex) || 0].learnerId);
    const button = $("[data-action='send-message']");
    window.schoolshieldChatSending = true;
    if (button) button.disabled = true;
    try {
      if (!child?.id) throw new Error("This conversation is not linked to a learner. Refresh the page and select the parent again.");
      if (text.length > 2000) throw new Error("Keep your message under 2,000 characters.");
      // Finish queued staff changes before the endpoint appends to the workspace.
      if (window.schoolshieldWorkspaceSaveQueue) await window.schoolshieldWorkspaceSaveQueue;
      const response = await window.schoolshieldFunctionRequest("parent-chat", { learner_id: child.id, text });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result.error || "The message could not be saved. Please try again.");
      if (input.value.trim() === text) input.value = "";
      const currentInput = $("#chatInput");
      if (currentInput?.value.trim() === text) currentInput.value = "";
      try {
        await refreshCloudWorkspace(true);
      } catch (error) {
        modal("Message sent", '<p class="muted">Your message was saved. Refresh the conversation to load the latest messages.</p>');
      }
    } catch (error) {
      const message = String(error.message || "Check your connection and try again.")
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      modal("Message not sent", `<p class="muted">${escapeHtml(message)}</p>`);
    } finally {
      window.schoolshieldChatSending = false;
      if (button) button.disabled = false;
      const currentButton = $("[data-action='send-message']");
      if (currentButton) currentButton.disabled = false;
    }
    return;
  }
  if (Array.isArray(getState()[storeKey])) {
    persist((state) => {
      const conversation =
        state[storeKey][Number(chatIndex)] || state[storeKey][0];
      if (conversation)
        conversation.messages.push({
          from: sender,
          sender: userName(),
          text,
          date: todayLabel(),
          sentAt: new Date().toISOString(),
        });
    });
  } else {
    persist((state) => {
      state.chatExtras = state.chatExtras || {};
      state.chatExtras[storeKey] = state.chatExtras[storeKey] || [];
      state.chatExtras[storeKey].push({
        from: sender,
        sender: userName(),
        text,
        date: todayLabel(),
        sentAt: new Date().toISOString(),
      });
    });
  }
  input.value = "";
  render();
}

function exportCsv() {
  const rows = [
    [
      "Class",
      "Grade",
      "Teacher",
      "Learners",
      "Attendance",
      "Test average",
      "Pass rate",
    ],
  ];
  for (const c of classes()) {
    const st = classStats(c.id);
    rows.push([
      c.id,
      c.grade,
      c.teacher,
      st.learners,
      st.attendance,
      classTestAverage(c.id),
      st.passRate,
    ]);
  }
  const csv = rows
    .map((r) =>
      r.map((x) => '"' + String(x).replace(/"/g, '""') + '"').join(","),
    )
    .join("\n");
  downloadTextFile("schoolshield-class-report.csv", csv);
}

function filterTable(query, selector) {
  const q = query.toLowerCase();
  $$(selector).forEach((row) => {
    row.style.display = row.innerText.toLowerCase().includes(q) ? "" : "none";
  });
}

/* --------------------------------- render -------------------------------- */
function patchLiveChat(html) {
  if (!["parent-chat", "teacher-chat", "sgb-chat"].includes(page())) return false;
  const live = $(".chat-window");
  if (!live) return false;
  const template = document.createElement("template");
  template.innerHTML = html;
  const incoming = template.content.querySelector(".chat-window");
  if (!incoming || live.dataset.conversation !== incoming.dataset.conversation) return false;
  const messages = live.querySelector(".messages");
  const nextMessages = incoming.querySelector(".messages");
  if (messages.innerHTML !== nextMessages.innerHTML) {
    const scrollTop = messages.scrollTop;
    const atBottom = messages.scrollHeight - messages.clientHeight - scrollTop <= 60;
    messages.innerHTML = nextMessages.innerHTML;
    messages.scrollTop = atBottom ? messages.scrollHeight : scrollTop;
  }
  // Never replace the composer, input or their ancestors. Focus, selection,
  // IME composition and browser keyboard state therefore remain untouched.
  const head = live.querySelector(".chat-head");
  const nextHead = incoming.querySelector(".chat-head");
  if (head.innerHTML !== nextHead.innerHTML) head.innerHTML = nextHead.innerHTML;
  const send = live.querySelector("[data-action='send-message']");
  const nextSend = incoming.querySelector("[data-action='send-message']");
  if (send && nextSend) Object.assign(send.dataset, nextSend.dataset);
  for (const selector of [".chat-contact-grid", ".chat-list"]) {
    const current = $(selector), next = template.content.querySelector(selector);
    if (current && next && current.innerHTML !== next.innerHTML) {
      current.innerHTML = next.innerHTML;
      $$('[data-action]', current).forEach(button => {
        button.onclick = () => action(button.dataset.action, button);
      });
    }
  }
  return true;
}
function render() {
  // Keep selected File objects and the original form mounted until its upload
  // finishes or is retried. Cloud data may refresh without replacing the form.
  if (window.schoolshieldPendingDocumentRecord || window.schoolshieldDocumentCapture) return;
  const announcementDraft = page() === "announcements" ? Object.fromEntries(
    ["annTitle", "annBody", "audienceSelect", "deliverySelect"].map(id => [id, $("#" + id)?.value]),
  ) : {};
  const chatInput = $("#chatInput");
  const oldMessages = $(".messages");
  const oldScrollTop = oldMessages?.scrollTop;
  const readingHistory = oldMessages && oldMessages.scrollHeight - oldMessages.clientHeight - oldMessages.scrollTop > 60;
  const chatDraft = chatInput?.value;
  const chatFocused = chatInput && document.activeElement === chatInput;
  const chatSelection = chatInput ? [chatInput.selectionStart, chatInput.selectionEnd] : null;
  if (!allowed()) {
    const first = ACCESS[role()]?.[0] || "dashboard";
    if (page() !== first) {
      const target = NAV.find((n) => n[0] === first);
      return go(target ? target[2] : "dashboard.html");
    }
  }
  const p = page();
  let html;
  if (p === "dashboard") html = dashboard();
  else if (p === "incidents") html = incidents();
  else if (p === "visitors") html = visitors();
  else if (p === "notifications") html = notifications();
  else if (p === "leadership") html = leadership();
  else if (p === "learners") html = learnersPage();
  else if (p === "class-records") html = classRecords();
  else if (p === "parents") html = parents();
  else if (p === "staff") html = staff();
  else if (p === "teacher-performance") html = window.SchoolShieldTeacherPerformance.view();
  else if (p === "teacher-targets") html = window.SchoolShieldTeacherTargets.viewOwn();
  else if (p === "my-performance") html = window.SchoolShieldMyPerformance.view();
  else if (p === "security") html = security();
  else if (p === "security-officers") html = securityOfficers();
  else if (p === "reports") html = reports();
  else if (p === "settings") html = settings();
  else if (p === "announcements") html = announcements();
  else if (p === "sick-notices") html = sickNotices();
  else if (p === "sick-notice") html = parentSickNoticePage();
  else if (p === "appointments") html = appointments();
  else if (p === "user-management") html = window.SchoolShieldUsers.page();
  else if (p === "school-records") html = window.SchoolShieldRecords.view();
  else if (p === "account-requests") html = accountRequests();
  else if (p === "student-records") html = studentRecords();
  else if (p === "student-record") html = studentRecord();
  else if (p === "student-reports") html = studentReports();
  else if (p === "report-compilation") html = reportCompilationPage();
  else if (p === "test-scores") html = testScores();
  else if (p === "attendance-register") html = dailyAttendanceRegister();
  else if (p === "teacher-chat") html = teacherChat();
  else if (p === "parent-chat") html = parentChat();
  else if (p === "sgb-chat") html = sgbChat();
  else html = dashboard();
  if (patchLiveChat(html)) return;
  $("#app").innerHTML = html;
  bind();
  Object.entries(announcementDraft).forEach(([id, value]) => {
    const field = $("#" + id);
    if (field && value !== undefined) field.value = value;
  });
  if (page() === "announcements") {
    const button = $("[data-action='send-announcement']");
    if (button) button.disabled = Boolean(window.schoolshieldAnnouncementSending);
  }
  const nextChatInput = $("#chatInput");
  if (nextChatInput && chatDraft !== undefined) {
    nextChatInput.value = chatDraft;
    if (chatFocused) {
      nextChatInput.focus({ preventScroll: true });
      nextChatInput.setSelectionRange(...chatSelection);
    }
  }
  if (readingHistory) {
    const nextMessages = $(".messages");
    if (nextMessages) requestAnimationFrame(() => { nextMessages.scrollTop = oldScrollTop; });
  }
}

