async function loadAccountRequestDashboardAlert() {
  const client = window.schoolshieldSupabase;
  if (!client || !["principal", "clerk"].includes(role())) return;
  const { count } = await client
    .from("account_request_notifications")
    .select("id", { count: "exact", head: true })
    .eq("notification_type", "account_request")
    .is("read_at", null);
  window.schoolshieldPendingAccountAlerts = count || 0;
  if (!count || page() !== "dashboard") return;
  const content = $(".content");
  if (!content || $("#accountApprovalDashboardAlert")) return;
  content.insertAdjacentHTML(
    "afterbegin",
    `<section class="panel" id="accountApprovalDashboardAlert" style="border-left:4px solid #e6a400"><div class="panel-head"><div><span class="pill">Action required</span><h3>${escapeHtml(count)} new account request${escapeHtml(count === 1 ? "" : "s")}</h3><p>A parent, teacher or security officer is waiting for approval.</p></div><a class="btn primary" href="account-requests.html">Review requests</a></div></section>`,
  );
}

async function loadAccountRequests() {
  const client = window.schoolshieldSupabase,
    rows = $("#accountRequestRows");
  if (!client || !rows) return;
  const { data, error } = await client
    .from("account_requests")
    .select("id, display_name, email, requested_role, created_at, invitation_method, phone")
    .eq("status", "pending")
    .order("created_at");
  await client
    .from("account_request_notifications")
    .update({ read_at: new Date().toISOString() })
    .eq("notification_type", "account_request")
    .is("read_at", null);
  window.schoolshieldPendingAccountAlerts = 0;
  if (error) {
    rows.innerHTML = `<tr><td colspan="5" class="muted">${escapeHtml(error.message)}</td></tr>`;
    return;
  }
  const roles = [
    "parent",
    "teacher",
    "security",
    "sgb",
    "deputy",
    "clerk",
    "principal",
  ];
  rows.innerHTML = data?.length
    ? data
        .map(
          (request) =>
            `<tr><td><b>${escapeHtml(request.display_name)}</b><small>${escapeHtml(new Date(request.created_at).toLocaleDateString())}</small></td><td>${escapeHtml(request.email)}<small>${escapeHtml(request.invitation_method === "sms" ? "SMS" : "Email")}</small></td><td>${escapeHtml(ROLE_NAMES[request.requested_role])}</td><td><select class="select" data-approval-role="${escapeHtml(request.id)}">${roles.map((value) => `<option value="${escapeHtml(value)}" ${escapeHtml(value === request.requested_role ? "selected" : "")}>${escapeHtml(ROLE_NAMES[value])}</option>`).join("")}</select></td><td><span class="action-row"><button class="btn small primary" data-action="approve-account-request" data-request="${escapeHtml(request.id)}">Approve &amp; invite</button><button class="btn small ghost" data-action="approve-account-request" data-delivery="setup_link" data-request="${escapeHtml(request.id)}">Approve &amp; setup link</button><button class="btn small ghost" data-action="reject-account-request" data-request="${escapeHtml(request.id)}">Reject</button></span></td></tr>`,
        )
        .join("")
    : '<tr><td colspan="5" class="muted">No pending account requests.</td></tr>';
  $$('[data-action="approve-account-request"]', rows).forEach(
    (button) => (button.onclick = () => action(button.dataset.action, button)),
  );
  $$('[data-action="reject-account-request"]', rows).forEach(
    (button) => (button.onclick = () => action(button.dataset.action, button)),
  );
}

async function approveAccountRequest(id, delivery = "preferred") {
  const client = window.schoolshieldSupabase,
    approvedRole = $(`[data-approval-role="${id}"]`)?.value;
  if (!client || !approvedRole) return;
  const {
    data: { session },
  } = await client.auth.getSession();
  const setupPath = location.pathname.replace(/[^/]+$/, "account-setup.html");
  const response = await fetch(
    `${window.SCHOOLSHIELD_SUPABASE_CONFIG.url}/functions/v1/approve-account`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session?.access_token || ""}`,
        apikey: window.SCHOOLSHIELD_SUPABASE_CONFIG.publishableKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        request_id: id,
        role: approvedRole,
        delivery,
        redirect_to: `${location.origin}${setupPath}`,
      }),
    },
  );
  const result = await response.json().catch(() => ({}));
  if (!response.ok)
    return alert(result.error || "Could not approve this account.");
  if (delivery === "setup_link" && result.setup_link) {
    const link = String(result.setup_link);
    let trustedLink = "";
    try {
      if (
        new URL(link).pathname.endsWith("/account-setup.html") && (new URL(link).protocol === "https:" || (new URL(link).protocol === "http:" && ["localhost", "127.0.0.1", "[::1]"].includes(new URL(link).hostname)))
      )
        trustedLink = link.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
    } catch (_) {
      /* Do not render an invalid link. */
    }
    if (trustedLink) {
      modal(
        "Account approved",
        `<p><b>The account has been approved.</b> No email was sent. Open this one-time setup link to test the applicant onboarding page.</p><div class="modal-foot"><a class="btn primary" href="${escapeHtml(trustedLink)}" target="_blank" rel="noopener">Open setup page</a><button class="btn ghost" data-action="close-modal">Done</button></div>`,
      );
    } else
      alert(
        "The account was approved, but the setup link could not be displayed safely.",
      );
  } else {
    modal(
      "Account approved",
      `<p><b>The account has been approved.</b> ${escapeHtml(result.message === "Account approved. The SMS provider accepted the invitation for delivery." ? "The SMS provider accepted the invitation for delivery." : "An invitation email has been sent.")}</p><div class="modal-foot"><button class="btn primary" data-action="close-modal">Done</button></div>`,
    );
  }
  loadAccountRequests();
}

async function rejectAccountRequest(id) {
  if (
    !confirm(
      "Reject this account request? The applicant will not receive an invitation.",
    )
  )
    return;
  const client = window.schoolshieldSupabase;
  if (!client) return;
  const {
    data: { session },
  } = await client.auth.getSession();
  const response = await fetch(
    `${window.SCHOOLSHIELD_SUPABASE_CONFIG.url}/functions/v1/approve-account`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session?.access_token || ""}`,
        apikey: window.SCHOOLSHIELD_SUPABASE_CONFIG.publishableKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ request_id: id, action: "reject" }),
    },
  );
  const result = await response.json().catch(() => ({}));
  if (!response.ok)
    return alert(result.error || "Could not reject this request.");
  modal(
    "Account request rejected",
    `<p>The request has been rejected and no account invitation was sent.</p><div class="modal-foot"><button class="btn primary" data-action="close-modal">Done</button></div>`,
  );
  loadAccountRequests();
}

function initWorkspaceChrome() {
  const sidebar = $(".sidebar");
  const main = $(".main");
  const topActions = $(".top-actions");
  if (!sidebar || !main || !topActions) return;
  if (!$("#refreshWorkspace")) {
    const refresh = document.createElement("button");
    refresh.id = "refreshWorkspace";
    refresh.className = "icon-btn";
    refresh.title = "Refresh school data";
    refresh.setAttribute("aria-label", "Refresh school data");
    refresh.textContent = "↻";
    refresh.onclick = refreshWorkspaceManually;
    topActions.prepend(refresh);
  }
  const nav = sidebar.querySelector("nav");
  const setMobileNav = () => {
    if (!nav) return;
    nav.style.display = "flex";
    nav.style.flexDirection = "column";
    nav.style.gridTemplateColumns = "";
  };
  const setSidebarState = (compact) => {
    sidebar.dataset.compact = String(compact);
    setMobileNav();
    if (innerWidth <= 700) {
      sidebar.style.transform = compact ? "translateX(-105%)" : "translateX(0)";
      sidebar.style.position = "fixed";
      sidebar.style.zIndex = "40";
      sidebar.style.width = "min(280px, 85vw)";
      sidebar.inert = compact;
      sidebar.setAttribute("aria-hidden", String(compact));
      const backdrop = $("#mobileNavBackdrop");
      if (backdrop) backdrop.hidden = compact;
      $("#sidebarToggle")?.setAttribute("aria-expanded", String(!compact));
      main.style.marginLeft = "0";
      main.style.width = "100%";
      return;
    }
    const rail = compact || innerWidth <= 980;
    sidebar.inert = false;
    sidebar.removeAttribute("aria-hidden");
    const backdrop = $("#mobileNavBackdrop");
    if (backdrop) backdrop.hidden = true;
    sidebar.style.transform = "";
    sidebar.style.width = rail ? "70px" : "252px";
    sidebar
      .querySelectorAll(
        ".brand div, .menu-title, .nav-item span:not(.icon):not(.nav-update), .role-card div:nth-child(2), .logout span",
      )
      .forEach((element) => (element.style.display = rail ? "none" : ""));
    main.style.marginLeft = rail ? "70px" : "252px";
    main.style.width = rail ? "calc(100% - 70px)" : "calc(100% - 252px)";
  };
  if (!$("#mobileNavBackdrop")) {
    const backdrop = document.createElement("button");
    backdrop.id = "mobileNavBackdrop";
    backdrop.className = "mobile-nav-backdrop";
    backdrop.setAttribute("aria-label", "Close navigation");
    backdrop.hidden = true;
    backdrop.onclick = () => setSidebarState(true);
    main.before(backdrop);
  }
  sidebar.onkeydown = (event) => { if (event.key === "Escape") { setSidebarState(true); $("#sidebarToggle")?.focus(); } };
  if (!$("#sidebarToggle")) {
    const toggle = document.createElement("button");
    toggle.id = "sidebarToggle";
    toggle.className = "icon-btn";
    toggle.title = "Toggle navigation";
    toggle.setAttribute("aria-label", "Toggle navigation");
    toggle.textContent = "☰";
    const titleArea = $(".topbar > div:first-child");
    if (titleArea) {
      titleArea.prepend(toggle);
      titleArea.style.display = "flex";
      titleArea.style.alignItems = "center";
      titleArea.style.gap = "12px";
    } else topActions.prepend(toggle);
    toggle.onclick = () => {
      setSidebarState(sidebar.dataset.compact !== "true");
    };
  }
  if (innerWidth <= 700) {
    setSidebarState(true);
  } else if (sidebar.dataset.compact === "true") {
    setSidebarState(true);
  } else {
    setSidebarState(false);
  }
  if (!window.__schoolshieldResponsiveChrome) {
    window.__schoolshieldResponsiveChrome = true;
    let resizeTimer;
    window.addEventListener("resize", () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(render, 140);
    });
  }
  if (!$("#notificationCenter")) {
    const drawer = document.createElement("aside");
    drawer.id = "notificationCenter";
    drawer.style.cssText =
      "display:none;position:fixed;right:22px;top:78px;width:min(380px,calc(100vw - 24px));max-height:calc(100vh - 100px);overflow:auto;z-index:60;background:#fff;border:1px solid #dce6e8;border-radius:14px;box-shadow:0 18px 45px rgba(4,34,42,.18);padding:14px";
    document.body.appendChild(drawer);
  }
}
function notificationCenterMarkup() {
  const notices = notificationsForRole();
  const deliveryNotice = window.schoolshieldAssignmentNoticeError ? `<p role="alert">${announcementText(window.schoolshieldAssignmentNoticeError)}</p>` : "";
  return `${deliveryNotice}<div style="display:flex;justify-content:space-between;align-items:start;border-bottom:1px solid #e3e9eb;padding-bottom:11px"><div><b style="font-size:14px">Notification centre</b><small style="display:block;color:#71838a">${escapeHtml(notices.filter((notice) => !notice.read).length)} unread</small></div><button class="icon-btn" id="closeNotifications" title="Close">×</button></div><input class="input" id="notificationSearch" style="margin:10px 0" placeholder="Search notifications..."><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px"><select class="select"><option>All types</option></select><select class="select"><option>All priority</option></select><select class="select"><option>Any date</option></select></div><div id="notificationItems" style="margin-top:12px">${notices.map((notice) => `<button class="notification-center-item" data-action="view-notification" data-notification="${escapeHtml(notice.id)}" style="width:100%;text-align:left;border:1px solid #dce6e8;border-radius:12px;background:${escapeHtml(notice.read ? "#fff" : "#f2f8ff")};padding:12px;margin-bottom:9px;cursor:pointer"><div style="display:flex;justify-content:space-between;gap:8px"><b>${escapeHtml(notice.title)}</b>${badge(notice.priority)}</div><small style="display:block;color:#60747a;margin:5px 0">${escapeHtml(notice.description)}</small><small>${escapeHtml(notice.category)} · ${escapeHtml(notificationTime(notice))}</small></button>`).join("") || '<p class="muted">No notifications.</p>'}</div><div style="display:flex;justify-content:space-between;border-top:1px solid #e3e9eb;padding-top:10px"><button class="btn small" id="drawerMarkRead">Mark all read</button><a class="text-link" href="notifications.html">View all →</a></div>`;
}
function toggleNotificationCenter() {
  const drawer = $("#notificationCenter");
  if (!drawer) return;
  const opening = drawer.style.display === "none";
  drawer.style.display = opening ? "block" : "none";
  if (!opening) return;
  drawer.innerHTML = notificationCenterMarkup();
  $$("[data-action]", drawer).forEach(
    (button) => (button.onclick = () => action(button.dataset.action, button)),
  );
  $("#closeNotifications", drawer).onclick = () =>
    (drawer.style.display = "none");
  $("#drawerMarkRead", drawer).onclick = async () => {
    if (await markVisibleNotificationsRead()) { drawer.style.display = "none"; toggleNotificationCenter(); }
  };
  $("#notificationSearch", drawer).oninput = (event) =>
    $$(".notification-center-item", drawer).forEach(
      (item) =>
        (item.style.display = item.innerText
          .toLowerCase()
          .includes(event.target.value.toLowerCase())
          ? ""
          : "none"),
    );
}
function bind() {
  initWorkspaceChrome();
  updateTeachingAssignmentBadge();
  if (page() === "teacher-performance") window.SchoolShieldTeacherPerformance.bind();
  if (page() === "teacher-targets") window.SchoolShieldTeacherTargets.bindOwn();
  if (page() === "my-performance") window.SchoolShieldMyPerformance.bindOwn();
  if (page() === "user-management") window.SchoolShieldUsers.bind();
  if (page() === "school-records") window.SchoolShieldRecords.bind();
  markRequiredFields(document);
  if (page() === "account-requests") loadAccountRequests();
  if (page() === "dashboard") loadAccountRequestDashboardAlert();
  if (page() === "dashboard") window.SchoolShieldTeacherDashboard?.bindHome();
  if (page() === "dashboard") {
    const quickHeading = $$("h3").find(
      (heading) => heading.textContent === "Quick access",
    );
    const quickPanel = quickHeading && quickHeading.closest("section");
    const dashboardPanels = $(".dashboard-grid");
    if (quickPanel && dashboardPanels) dashboardPanels.before(quickPanel);
  }
  $("#logout")?.addEventListener("click", async () => {
    await window.schoolshieldSupabase?.auth.signOut();
    sessionStorage.removeItem("schoolshieldRole");
    sessionStorage.removeItem("schoolshieldSession");
    location.href = "login.html";
  });
  $("#globalBell")?.addEventListener("click", toggleNotificationCenter);
  $$("[data-nav]").forEach(
    (b) =>
      (b.onclick = () => {
        const target = NAV.find((x) => x[0] === b.dataset.nav);
        if (target) go(target[2]);
      }),
  );
  $$("[data-action]").forEach(
    (b) => (b.onclick = () => action(b.dataset.action, b)),
  );
  $$("[data-week-status]").forEach((box) => {
    box.onchange = () => {
      if (!box.checked) return;
      $$(
        `[data-week-learner="${box.dataset.weekLearner}"][data-week-day="${box.dataset.weekDay}"]`,
      ).forEach((other) => {
        if (other !== box) other.checked = false;
      });
    };
  });
  $("#markRead")?.addEventListener("click", async () => { if (await markVisibleNotificationsRead()) render(); });
  $$("[data-visitor]:not([data-action])").forEach(
    (b) => (b.onclick = () => visitorModal(b.dataset.visitor)),
  );
  $("#visitorSearch")?.addEventListener("input", (e) =>
    filterTable(e.target.value, ".visitor-row"),
  );
  $("#incidentSearch")?.addEventListener("input", (e) =>
    filterTable(e.target.value, ".incident-row"),
  );
  $("#learnerSearch")?.addEventListener("input", (e) =>
    filterTable(e.target.value, ".class-card"),
  );
  $("#studentSearch")?.addEventListener("input", (e) =>
    filterTable(e.target.value, ".student-row"),
  );
  ["incidentDate", "sickDate", "attendanceDate"].forEach((id) => {
    const dateInput = document.getElementById(id);
    if (dateInput) dateInput.max = todayIso();
  });
  $("#chatSearch")?.addEventListener("input", (event) => {
    const query = event.target.value.toLowerCase();
    $$("[data-chat-contact]").forEach(
      (contact) =>
        (contact.style.display = contact.innerText.toLowerCase().includes(query)
          ? ""
          : "none"),
    );
  });
  $("#exportCsv")?.addEventListener("click", exportCsv);
  $("#audienceSelect")?.addEventListener("change", (e) => {
    const opt = e.target.options[e.target.selectedIndex];
    const count = $("#audienceCount");
    if (count) count.textContent = opt.dataset.count || "0";
  });
  $("#chatInput")?.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      const sendButton = $("[data-action='send-message']");
      if (sendButton) action("send-message", sendButton);
    }
  });
  const messagePane = $(".messages");
  if (messagePane)
    requestAnimationFrame(() => {
      messagePane.scrollTop = messagePane.scrollHeight;
    });
  setTimeout(showPendingSickNoticePopup, 0);
  setTimeout(showClerkAssessmentPopup, 0);
  setTimeout(showTeacherCriticalMarkPopup, 0);
}

/* Both live and optional demo schools use real Supabase authentication. */
async function startWorkspace() {
  const client = window.schoolshieldSupabase;
  if (!client) return location.replace("login.html");
  if (client) {
    const {
      data: { session },
    } = await client.auth.getSession();
    if (!session?.user) return location.replace("login.html");
    const { data: profile } = await client
      .from("profiles")
      .select("role, display_name, account_status, requires_setup, onboarding_completed_at, school:schools(id, code, name, data_mode)")
      .eq("id", session.user.id)
      .maybeSingle();
    const school = Array.isArray(profile?.school)
      ? profile.school[0]
      : profile?.school;
    if (!profile || !school || profile.account_status === "Inactive" || (profile.requires_setup && !profile.onboarding_completed_at)) {
      await client.auth.signOut();
      return location.replace("login.html");
    }
    let principalName =
      profile.role === "principal" ? profile.display_name : "";
    if (!principalName) {
      const { data: leadership } = await client.rpc("get_school_leadership");
      principalName = leadership?.[0]?.display_name || school.name + " Principal";
    }
    sessionStorage.setItem(
      "schoolshieldSession",
      JSON.stringify({
        userId: session.user.id,
        schoolId: school.id,
        schoolCode: school.code,
        schoolName: school.name,
        schoolMode: school.data_mode || "live",
        principalName,
        role: profile.role,
        displayName: profile.display_name,
        email: session.user.email,
      }),
    );
    sessionStorage.setItem("schoolshieldRole", profile.role);
    SCHOOL = activeSchool();
    await connectCloudWorkspace(session.user, profile, school);
    await loadTeachingAssignmentNotifications();
    startWorkspaceRealtime();
    startWorkspaceAutoRefresh();
    if (["principal", "clerk"].includes(profile.role)) {
      const { count } = await client
        .from("account_request_notifications")
        .select("id", { count: "exact", head: true })
        .eq("notification_type", "account_request")
        .is("read_at", null);
      window.schoolshieldPendingAccountAlerts = count || 0;
    }
  }
  if (
    !sessionStorage.getItem("schoolshieldSession") &&
    !sessionStorage.getItem("schoolshieldRole")
  )
    return location.replace("login.html");
  render();
  if (sessionStorage.getItem(`${workspaceCacheKey()}:pending`)) {
    modal('Unsynced draft retained', '<p>This tab has changes that Supabase has not confirmed. You can retry the draft or download it before closing this tab. Conflicting server records will not be overwritten.</p><button class="btn primary" data-action="retry-school-draft">Retry saved draft</button><button class="btn" data-action="export-school-draft">Download draft</button>');
  }
}
startWorkspace();
